-- Opt-in, bounded resumption; historical tasks and accounting records stay intact.
CREATE TABLE queue_automation_policies(firm_id TEXT NOT NULL,company_id TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),allow_verified_supplements INTEGER NOT NULL CHECK(allow_verified_supplements IN(0,1)),version INTEGER NOT NULL CHECK(version>0),updated_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL,last_scanned_at TEXT,PRIMARY KEY(firm_id,company_id),FOREIGN KEY(firm_id,company_id) REFERENCES firm_clients(firm_id,company_id));
CREATE TABLE proposal_resume_watch(job_id TEXT PRIMARY KEY REFERENCES proposal_jobs(id),generation INTEGER NOT NULL CHECK(generation>0),blocker TEXT NOT NULL,next_check_at TEXT NOT NULL,check_count INTEGER NOT NULL DEFAULT 0,claim_token TEXT);
CREATE INDEX idx_resume_due ON proposal_resume_watch(next_check_at,job_id);
CREATE UNIQUE INDEX idx_proposal_resume_scope ON proposal_jobs(id,event_id,firm_id,company_id,book_id);
CREATE TABLE proposal_resume_events(job_id TEXT NOT NULL,generation INTEGER NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,book_id TEXT NOT NULL,event_id TEXT NOT NULL,execution_user_id TEXT NOT NULL REFERENCES users(id),reason_json TEXT NOT NULL CHECK(json_valid(reason_json)),created_at TEXT NOT NULL,PRIMARY KEY(job_id,generation),FOREIGN KEY(job_id,event_id,firm_id,company_id,book_id) REFERENCES proposal_jobs(id,event_id,firm_id,company_id,book_id));
CREATE TABLE queue_verified_evidence_versions(event_id TEXT NOT NULL,fact_version INTEGER NOT NULL,response_id TEXT NOT NULL UNIQUE REFERENCES case_responses(id),firm_id TEXT NOT NULL,company_id TEXT NOT NULL,book_id TEXT,source_id TEXT,draft_id TEXT,draft_version INTEGER,created_at TEXT NOT NULL,PRIMARY KEY(event_id,fact_version),FOREIGN KEY(event_id,firm_id,company_id) REFERENCES business_events(id,firm_id,company_id));
CREATE TABLE processing_job_metrics(job_kind TEXT NOT NULL CHECK(job_kind IN('ocr','proposal')),job_id TEXT NOT NULL,generation INTEGER NOT NULL,attempt_no INTEGER NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,event_id TEXT NOT NULL,book_id TEXT,stage TEXT NOT NULL CHECK(stage IN('dependency_wait','eligible_queue_wait','claim_lock','model_call','validation_persistence','ocr_cache_reuse')),duration_ms INTEGER NOT NULL CHECK(duration_ms BETWEEN 0 AND 2678400000),created_at TEXT NOT NULL,PRIMARY KEY(job_kind,job_id,generation,attempt_no,stage),FOREIGN KEY(firm_id,company_id) REFERENCES firm_clients(firm_id,company_id));
CREATE INDEX idx_job_metrics_company ON processing_job_metrics(firm_id,company_id,created_at,stage);
CREATE INDEX idx_resume_events_book ON proposal_resume_events(firm_id,book_id,created_at);
CREATE TABLE queue_resume_signals(firm_id TEXT NOT NULL,company_id TEXT NOT NULL,event_id TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,signalled_at TEXT NOT NULL,PRIMARY KEY(firm_id,company_id,event_id,kind),FOREIGN KEY(firm_id,company_id) REFERENCES firm_clients(firm_id,company_id));
CREATE TRIGGER resume_signal_case_closed AFTER UPDATE OF state ON case_tasks WHEN NEW.state='closed' AND OLD.state<>'closed' BEGIN
 INSERT INTO queue_resume_signals(firm_id,company_id,event_id,kind,signalled_at) VALUES(NEW.firm_id,NEW.company_id,COALESCE(NEW.event_id,''),'case_closed',NEW.updated_at) ON CONFLICT(firm_id,company_id,event_id,kind) DO UPDATE SET revision=queue_resume_signals.revision+1,signalled_at=excluded.signalled_at;
 UPDATE proposal_resume_watch SET next_check_at='2000-01-01T00:00:00+00:00',claim_token=NULL WHERE job_id IN(SELECT id FROM proposal_jobs WHERE firm_id=NEW.firm_id AND company_id=NEW.company_id AND (NEW.event_id IS NULL OR event_id=NEW.event_id) AND status='needs_attention' ORDER BY created_at,id LIMIT 200);
END;
CREATE TRIGGER resume_signal_processing AFTER UPDATE ON ai_company_settings BEGIN
 INSERT INTO queue_resume_signals(firm_id,company_id,event_id,kind,signalled_at) VALUES(NEW.firm_id,NEW.company_id,'','processing_changed',NEW.updated_at) ON CONFLICT(firm_id,company_id,event_id,kind) DO UPDATE SET revision=queue_resume_signals.revision+1,signalled_at=excluded.signalled_at;
 UPDATE proposal_resume_watch SET next_check_at='2000-01-01T00:00:00+00:00',claim_token=NULL WHERE job_id IN(SELECT id FROM proposal_jobs WHERE firm_id=NEW.firm_id AND company_id=NEW.company_id AND status='needs_attention' ORDER BY created_at,id LIMIT 200);
END;
CREATE TRIGGER resume_signal_policy AFTER UPDATE ON model_company_policies BEGIN
 INSERT INTO queue_resume_signals(firm_id,company_id,event_id,kind,signalled_at) VALUES(NEW.firm_id,NEW.company_id,'','budget_changed',NEW.updated_at) ON CONFLICT(firm_id,company_id,event_id,kind) DO UPDATE SET revision=queue_resume_signals.revision+1,signalled_at=excluded.signalled_at;
 UPDATE proposal_resume_watch SET next_check_at='2000-01-01T00:00:00+00:00',claim_token=NULL WHERE job_id IN(SELECT id FROM proposal_jobs WHERE firm_id=NEW.firm_id AND company_id=NEW.company_id AND status='needs_attention' ORDER BY created_at,id LIMIT 200);
END;
CREATE TRIGGER resume_events_no_update BEFORE UPDATE ON proposal_resume_events BEGIN SELECT RAISE(ABORT,'Resume receipts are immutable'); END;
CREATE TRIGGER resume_events_no_delete BEFORE DELETE ON proposal_resume_events BEGIN SELECT RAISE(ABORT,'Resume receipts are immutable'); END;
CREATE TRIGGER evidence_versions_no_update BEFORE UPDATE ON queue_verified_evidence_versions BEGIN SELECT RAISE(ABORT,'Accepted evidence versions are immutable'); END;
CREATE TRIGGER evidence_versions_no_delete BEFORE DELETE ON queue_verified_evidence_versions BEGIN SELECT RAISE(ABORT,'Accepted evidence versions are immutable'); END;
CREATE TRIGGER job_metrics_no_update BEFORE UPDATE ON processing_job_metrics BEGIN SELECT RAISE(ABORT,'Metrics are append-only'); END;
CREATE TRIGGER job_metrics_no_delete BEFORE DELETE ON processing_job_metrics BEGIN SELECT RAISE(ABORT,'Metrics are append-only'); END;
CREATE TRIGGER resume_watch_insert AFTER INSERT ON proposal_jobs WHEN NEW.status='needs_attention' AND NEW.error_code IN('processing_disabled','ocr_unavailable','provider_unavailable','evidence_missing','case_pending','queue_capacity','quota_exhausted','pricing_missing','policy_invalid') BEGIN
 INSERT INTO proposal_resume_watch(job_id,generation,blocker,next_check_at) VALUES(NEW.id,NEW.generation,NEW.error_code,NEW.updated_at) ON CONFLICT(job_id) DO UPDATE SET generation=excluded.generation,blocker=excluded.blocker,next_check_at=excluded.next_check_at,claim_token=NULL;
END;
CREATE TRIGGER resume_watch_update AFTER UPDATE ON proposal_jobs WHEN NEW.status='needs_attention' AND NEW.error_code IN('processing_disabled','ocr_unavailable','provider_unavailable','evidence_missing','case_pending','queue_capacity','quota_exhausted','pricing_missing','policy_invalid') AND (NEW.status,NEW.error_code,NEW.generation) IS NOT(OLD.status,OLD.error_code,OLD.generation) BEGIN
 INSERT INTO proposal_resume_watch(job_id,generation,blocker,next_check_at) VALUES(NEW.id,NEW.generation,NEW.error_code,NEW.updated_at) ON CONFLICT(job_id) DO UPDATE SET generation=excluded.generation,blocker=excluded.blocker,next_check_at=excluded.next_check_at,claim_token=NULL;
END;
INSERT INTO proposal_resume_watch(job_id,generation,blocker,next_check_at) SELECT id,generation,error_code,updated_at FROM proposal_jobs WHERE status='needs_attention' AND error_code IN('processing_disabled','ocr_unavailable','provider_unavailable','evidence_missing','case_pending','queue_capacity','quota_exhausted','pricing_missing','policy_invalid');
CREATE TRIGGER queue_capture_evidence_fact AFTER UPDATE OF fact_version ON business_events WHEN NEW.fact_version=OLD.fact_version+1 AND NEW.payload=OLD.payload BEGIN
 INSERT INTO queue_verified_evidence_versions(event_id,fact_version,response_id,firm_id,company_id,book_id,source_id,draft_id,draft_version,created_at)
 SELECT NEW.id,NEW.fact_version,r.id,NEW.firm_id,NEW.company_id,m.book_id,m.source_id,m.draft_id,d.version,NEW.updated_at FROM case_responses r JOIN case_tasks t ON t.id=r.case_id LEFT JOIN business_mappings m ON m.event_id=t.event_id LEFT JOIN drafts d ON d.id=m.draft_id AND d.book_id=m.book_id WHERE t.event_id=NEW.id AND r.state='accepted' AND r.reviewed_by<>r.created_by AND t.state='in_review' AND t.evidence_revision=t.accepted_fact_revision+1 AND NOT EXISTS(SELECT 1 FROM queue_verified_evidence_versions v WHERE v.response_id=r.id) ORDER BY r.reviewed_at DESC,r.id DESC LIMIT 1;
END;
CREATE TRIGGER proposal_wait_metric AFTER UPDATE OF status ON proposal_jobs WHEN (OLD.status='waiting' AND NEW.status='queued') OR (OLD.status IN('queued','retry_wait') AND NEW.status='running') BEGIN
 INSERT INTO processing_job_metrics(job_kind,job_id,generation,attempt_no,firm_id,company_id,event_id,book_id,stage,duration_ms,created_at)
 VALUES('proposal',NEW.id,NEW.generation,NEW.attempt_count,NEW.firm_id,NEW.company_id,NEW.event_id,NEW.book_id,CASE WHEN OLD.status='waiting' THEN 'dependency_wait' ELSE 'eligible_queue_wait' END,max(0,min(2678400000,CAST((julianday(NEW.updated_at)-julianday(CASE WHEN OLD.status='waiting' THEN OLD.updated_at ELSE max(OLD.updated_at,OLD.available_at) END))*86400000 AS INTEGER))),NEW.updated_at) ON CONFLICT DO NOTHING;
END;
CREATE TRIGGER ocr_wait_metric AFTER UPDATE OF status ON ocr_jobs WHEN OLD.status IN('queued','retry_wait') AND NEW.status='running' BEGIN
 INSERT INTO processing_job_metrics(job_kind,job_id,generation,attempt_no,firm_id,company_id,event_id,book_id,stage,duration_ms,created_at)
 VALUES('ocr',NEW.id,1,NEW.attempt_count,NEW.firm_id,NEW.company_id,NEW.event_id,NULL,'eligible_queue_wait',max(0,min(2678400000,CAST((julianday(NEW.updated_at)-julianday(max(OLD.updated_at,OLD.available_at)))*86400000 AS INTEGER))),NEW.updated_at) ON CONFLICT DO NOTHING;
END;
